script.setup:
// REBOUND (IAS15) integrated a star with a disk of 500 massless particles while a second
// star passed on a hyperbolic orbit (recipe rebound.disk-flyby → orbits.json). All
// snapshots go into one float texture; the vertex shader samples it to draw comet-like trails.
const data = await (await fetch(ctx.assets["orbits.json"])).json();
const gl = ctx.gl, B = data.bodies, F = data.frames;
const tex = ctx.utils.uploadDataTexture(gl, null, B, F, new Float32Array(data.positions), { internalFormat: gl.RGB32F, format: gl.RGB, type: gl.FLOAT, filter: gl.NEAREST });
// No vertex attributes: every position comes from the texture (by gl_InstanceID).
const vao = gl.createVertexArray();
const common = `#version 300 es
precision highp float; precision highp sampler2D;
uniform sampler2D u_pos; uniform float u_frame; uniform mat4 u_mvp; uniform vec3 u_center;
vec3 at(int body, float f){
  f = clamp(f, 0.0, ${F - 1}.0); int i = int(floor(f)); int j = min(i + 1, ${F - 1});
  vec3 a = texelFetch(u_pos, ivec2(body, i), 0).xyz, b = texelFetch(u_pos, ivec2(body, j), 0).xyz;
  return mix(a, b, fract(f)) - u_center;
}
float info(int body){ if (body < 2) return body == 0 ? -1.0 : -2.0;
  return length(texelFetch(u_pos, ivec2(body, 0), 0).xyz - texelFetch(u_pos, ivec2(0, 0), 0).xyz); }
vec3 tint(float r){ if (r < -1.5) return vec3(1.0, 0.55, 0.35); if (r < 0.0) return vec3(1.0, 0.95, 0.8);
  return mix(vec3(0.45, 0.75, 1.0), vec3(0.95, 0.5, 0.9), smoothstep(0.45, 1.5, r)); }`;
const trailVs = `${common}
uniform float u_trail; uniform float u_steps; out vec4 v_color;
void main(){
  float a_info = info(gl_InstanceID);
  float k = float(gl_VertexID) / u_steps;
  vec3 p = at(gl_InstanceID, u_frame - k * u_trail);
  float fade = pow(1.0 - k, 1.6);
  v_color = vec4(tint(a_info) * fade * (a_info < 0.0 ? 1.0 : 0.55), 1.0);
  gl_Position = u_mvp * vec4(p, 1.0);
}`;
const headVs = `${common}
uniform float u_px; out vec4 v_color; out float v_star;
void main(){
  float a_info = info(gl_InstanceID);
  vec3 p = at(gl_InstanceID, u_frame);
  v_color = vec4(tint(a_info), 1.0); v_star = a_info < 0.0 ? 1.0 : 0.0;
  gl_Position = u_mvp * vec4(p, 1.0);
  gl_PointSize = a_info < 0.0 ? (a_info < -1.5 ? 70.0 : 90.0) * u_px / max(gl_Position.w, 0.5) : max(5.0 * u_px / max(gl_Position.w, 0.5), 1.5);
}`;
Object.assign(ctx.state, {
  data, tex, vao, B, F,
  camera: ctx.utils.createOrbitCamera({ distance: 9, theta: 0.4, phi: 0.95 }),
  trail: ctx.utils.createProgram(trailVs, `#version 300 es
precision highp float; in vec4 v_color; out vec4 outColor; void main(){ outColor = v_color; }`),
  head: ctx.utils.createProgram(headVs, `#version 300 es
precision highp float; in vec4 v_color; in float v_star; out vec4 outColor;
void main(){ vec2 q = gl_PointCoord * 2.0 - 1.0; float d = dot(q, q); if (d > 1.0) discard;
  float core = v_star > 0.5 ? exp(-d * 40.0) : exp(-d * 4.0); float halo = v_star * (exp(-d * 6.0) * 0.35 + (1.0 - d) * 0.08);
  outColor = vec4(v_color.rgb * (core + halo) + vec3(core * v_star), 1.0); }`),
  bg: ctx.utils.createProgram(ctx.utils.FULLSCREEN_VERTEX_SHADER, `#version 300 es
precision highp float; in vec2 v_uv; out vec4 outColor;
float h(vec2 p){ vec3 q = fract(vec3(p.xyx) * 0.1031); q += dot(q, q.yzx + 33.33); return fract((q.x + q.y) * q.z); }
void main(){ vec2 g = floor(v_uv * vec2(320.0, 180.0)); float s = step(0.996, h(g)) * h(g + 3.1);
  vec2 q = v_uv - 0.5; outColor = vec4(vec3(0.012, 0.014, 0.03) + vec3(0.03, 0.02, 0.05) * (1.0 - length(q) * 1.5) + s * 0.5, 1.0); }`),
});
ctx.publish("particles", B - 2);

script.render:
const s = ctx.state, gl = ctx.gl, u = ctx.uniforms, { mat4 } = ctx.utils, [w, h] = ctx.resolution;
const T = s.data.times[s.F - 1];
// Play through the flyby, hold a moment, loop.
const span = T / u.u_speed, hold = 2.5, t = (ctx.time % (span + hold));
const frame = Math.min(t / span, 1) * (s.F - 1);
// Follow the host star so the disk stays in view while the system drifts.
const i = Math.floor(frame), j = Math.min(i + 1, s.F - 1), f = frame - i, P = s.data.positions, o = (k) => k * s.B * 3;
const center = [0, 1, 2].map((c) => P[o(i) + c] * (1 - f) + P[o(j) + c] * f);
s.camera.update(ctx.mouse, ctx.mousePrev, ctx.mouseDown, ctx.keys, ctx.dt);
// The disk lies in x-y; tip it so y-up orbit controls look down on it.
const model = mat4.fromXRotation(-Math.PI / 2);
const mvp = mat4.multiply(s.camera.getProjectionMatrix(w / h, 45, 0.05, 200), mat4.multiply(s.camera.getViewMatrix(), model));
ctx.utils.drawFullscreen(s.bg);
gl.enable(gl.BLEND); gl.blendFunc(gl.ONE, gl.ONE);
const steps = 48;
gl.useProgram(s.trail);
ctx.utils.bindTexture(s.trail, "u_pos", s.tex, 0);
ctx.utils.setUniforms(s.trail, { u_mvp: mvp, u_frame: frame, u_center: center, u_trail: u.u_trail, u_steps: steps });
gl.bindVertexArray(s.vao);
gl.drawArraysInstanced(gl.LINE_STRIP, 0, steps + 1, s.B);
gl.useProgram(s.head);
ctx.utils.bindTexture(s.head, "u_pos", s.tex, 0);
ctx.utils.setUniforms(s.head, { u_mvp: mvp, u_frame: frame, u_center: center, u_px: h / 360 });
gl.drawArraysInstanced(gl.POINTS, 0, 1, s.B);
gl.bindVertexArray(null);
gl.disable(gl.BLEND);
ctx.publish("time", Number((frame / (s.F - 1) * T).toFixed(1)));
